    getQrCodeImage: {
        parameters: {
            query?: {
                /**
                 * @description Image format, in lower case. Any other value returns `400 validation_error` (never a
                 *     silent fallback to another format).
                 */
                format?: "png" | "svg";
                /**
                 * @description PNG only: side of the square in pixels, margin included, integer from 128 to 1024
                 *     (at least 256 for a QR code with a logo). A non-integer or out-of-range value returns
                 *     `400 validation_error`. Ignored for SVG
                 *     (vector, can be resized without loss — the format to prefer for large-format
                 *     printing).
                 */
                size?: number;
                /**
                 * @description `none`: standard rendering (black on white, squares, no logo), without the style of the
                 *     QR code. Missing: effective style of the QR code. Any other value, and a repeated
                 *     `style`, return `400 validation_error`. With required templates (Entreprise):
                 *     `403 template_locked`.
                 */
                style?: "none";
            };
            header?: {
                /** @description `ETag` value obtained from a previous call. */
                "If-None-Match"?: string;
            };
            path: {
                /** @description Identifier (`cuid`) of the QR code. */
                id: components["parameters"]["QrCodeIdParam"];
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Image of the QR code. */
            200: {
                headers: {
                    "RateLimit-Policy": components["headers"]["RateLimitPolicy"];
                    RateLimit: components["headers"]["RateLimit"];
                    /** @description Fingerprint of the image (format, size, encoded content and effective style). */
                    ETag?: string;
                    /** @description `attachment; filename="qr-suisse-<slug>.<png|svg>"` */
                    "Content-Disposition"?: string;
                    /** @description `private, no-cache` — authenticated response, never stored in a shared cache, revalidated on every use. */
                    "Cache-Control"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "image/png": string;
                    "image/svg+xml": string;
                };
            };
            /** @description The image has not changed since the `ETag` sent in `If-None-Match` — no body. */
            304: {
                headers: {
                    "RateLimit-Policy": components["headers"]["RateLimitPolicy"];
                    RateLimit: components["headers"]["RateLimit"];
                    /** @description Fingerprint of the image, identical to the one sent. */
                    ETag?: string;
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Invalid `format`, `size` or `style` parameter, repeated `style`, or `size` below 256 for a QR code with a logo. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ValidationError"];
                };
            };
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["ForbiddenOrTemplateLocked"];
            404: components["responses"]["NotFound"];
            /**
             * @description `rate_limited` — generic bucket exceeded (30 requests / 60 s per API key), too many
             *     requests refused with `401` from the same IP address (60 / 60 s, or 300 / 60 s per
             *     IPv6 /48 network), or, for the PNG format, bucket dedicated to renders exceeded
             *     (10 renders / 60 s per account).
             */
            429: {
                headers: {
                    "Retry-After": components["headers"]["RetryAfter"];
                    "RateLimit-Policy": components["headers"]["RateLimitPolicy"];
                    RateLimit: components["headers"]["RateLimit"];
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["RateLimitedError"];
                };
            };
            500: components["responses"]["InternalError"];
            503: components["responses"]["RenderBusy"];
        };
    };
